-- 90_VERIFY.sql — DMF0053 적용 확인 [20260827]
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_NAME IN ('PKG_DMF0053');
SELECT COUNT(*) AS INVALID_CNT FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND STATUS='INVALID' AND OBJECT_NAME IN ('PKG_DMF0053');
SELECT 'SCM_ADM_PROGRAM' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_PROGRAM WHERE PROGRAM_ID LIKE 'DMF0053%';  -- 기대 1
SELECT 'SCM_ADM_MNU_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID LIKE 'DMF0053%';  -- 기대 1
SELECT 'SCM_ADM_USER_GR_MNU_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID LIKE 'DMF0053%';  -- 기대 4
SELECT 'SCM_ADM_MNU_BTN_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID LIKE 'DMF0053%';  -- 기대 4
SELECT 'SCM_ADM_USER_GR_MNU_BTN_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID LIKE 'DMF0053%';  -- 기대 16
SELECT 'SCM_ADM_API_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID LIKE 'DMF0053%';  -- 기대 4
SELECT 'SCM_MST_SHEET_COLUMNS/CUST Fcst Waterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='DMF0053' AND SHEET_NAME='CUST Fcst Waterfall';  -- 기대 66
SELECT 'SCM_MST_SHEET_MEASURE/CUST Fcst Waterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID='DMF0053' AND SHEET_NAME='CUST Fcst Waterfall';  -- 기대 2
SELECT COUNT(*) AS GTT_CNT FROM ALL_TABLES WHERE OWNER='SCM_MGR' AND TEMPORARY='Y' AND TABLE_NAME IN ('GT_DM53_CALENDAR', 'GT_DM53_COLUMN_SETUP', 'GT_DM53_EDI_CALLOFF', 'GT_DM53_ITEM_SINGLE_V', 'GT_DM53_ITEM_SINGLE_VT', 'GT_DM53_RAW_DATA', 'GT_DM53_SCM_MST_SITE', 'GT_DM53_SITE_ITEM', 'GT_DMF0053_COLUMN_SETUP', 'GT_DMF0053_EDI_CALLOFF', 'GT_DMF0053_ITEM_SINGLE_V', 'GT_DMF0053_ITEM_SINGLE_V_T', 'GT_DMF0053_RAW_DATA', 'GT_DMF0053_SCM_MST_SITE', 'GT_DMF0053_SCM_MST_SITE_ITEM', 'GT_DMF0053_SELECT_MEASURE', 'GT_DMF0053_T');  -- 기대 17

-- ── V11~V13 조용한-실패 게이트 (hook #148 cloud-deploy-silent-failure-gates, 2026-08-28 — §4.7-B V11 미구현 재발 정정) ──
-- V11 메뉴 행 실존 + UNIT_TP_CD='D'/USE_YN='Y' (기대 1행) — 부재 시 SCM_ADM_USER_MNU_EDIT_AUTH_V INNER JOIN 으로 오류 없이 0행
SELECT 'V11-MNU' G, MNU_ID, UNIT_TP_CD, USE_YN FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID='DMF0053';
-- V11-B 테스트 계정 권한 뷰 반환 행 (기대 ≥1, 조회 Division 포함) — <TEST_USER> 를 실제 로그인 ID 로
SELECT 'V11-AUTH' G, UNIT_ID, EDIT_YN FROM SCM_MGR.SCM_ADM_USER_MNU_EDIT_AUTH_V WHERE USER_ID='<TEST_USER>' AND MNU_ID='DMF0053' ORDER BY 2;
-- V12 앱 계정 EXECUTE + private synonym (기대: 객체별 SCMP_APP 각 1행 — 없으면 40_GRANT_SYNONYM.sql) — 부재 시 화면 "SQL ERROR"(PLS-00201)
SELECT 'V12-GRANT' G, TABLE_NAME, GRANTEE FROM ALL_TAB_PRIVS WHERE TABLE_SCHEMA='SCM_MGR' AND PRIVILEGE='EXECUTE' AND GRANTEE='SCMP_APP' AND TABLE_NAME IN ('PKG_DMF0053','FN_GET_DM_MKT_OWNER_NAME','FN_STRING_SPLIT','UF_FX_STRING_SPLIT','DMF0002_GET_TITLESET_POPUP','SCM0002_SET_TITLESET_POPUP') ORDER BY 2;
SELECT 'V12-SYN' G, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER='SCMP_APP' AND TABLE_OWNER='SCM_MGR' AND SYNONYM_NAME IN ('PKG_DMF0053','FN_GET_DM_MKT_OWNER_NAME','FN_STRING_SPLIT','UF_FX_STRING_SPLIT','DMF0002_GET_TITLESET_POPUP','SCM0002_SET_TITLESET_POPUP') ORDER BY 2;
-- V13 PKG 본문이 V_PROGRAM_ID 로 읽는 종속 PROGRAM_ID 전부의 시트 메타 (기대: 각 PROGRAM_ID 행 > 0 — 사내 값은 22/22A 파일 주석)
SELECT 'V13-META' G, PROGRAM_ID, 'COLUMNS' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID IN ('DMF0053') GROUP BY PROGRAM_ID
UNION ALL SELECT 'V13-META', PROGRAM_ID, 'MEASURE', COUNT(*) FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID IN ('DMF0053') GROUP BY PROGRAM_ID ORDER BY 2,3;
